def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[()+*/,:=<>-]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "u-": 3,
        ":": 4,
    }

    def parse(expression):
        nodes = []
        operators = []
        argument_counts = []
        expecting_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "u-":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                if op == ":":
                    nodes.append(("range", left, right))
                else:
                    nodes.append(("binary", op, left, right))

        for match in token_pattern.finditer(expression):
            token = match.group()

            if token[0].isdigit():
                nodes.append(int(token))
                expecting_operand = False

            elif token in functions:
                operators.append(token)
                expecting_operand = True

            elif token == "(":
                operators.append(token)
                argument_counts.append(1)
                expecting_operand = True

            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expecting_operand = True

            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()

                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = nodes[-count:]
                    del nodes[-count:]
                    nodes.append(("call", function, arguments))

                expecting_operand = False

            elif token in precedence:
                op = "u-" if token == "-" and expecting_operand else token

                while operators and operators[-1] in precedence:
                    previous = operators[-1]
                    if precedence[previous] < precedence[op]:
                        break
                    if previous == op == "u-":
                        break
                    reduce_operator()

                operators.append(op)
                expecting_operand = True

            else:
                nodes.append(token)
                expecting_operand = False

        while operators:
            reduce_operator()

        return nodes[0]

    def argument_nodes(arguments):
        for node in arguments:
            if isinstance(node, tuple) and node[0] == "range":
                first, last = node[1], node[2]
                col1, col2 = sorted((ord(first[0]), ord(last[0])))
                row1, row2 = sorted((int(first[1:]), int(last[1:])))

                for row in range(row1, row2 + 1):
                    for col in range(col1, col2 + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            yield name
            else:
                yield node

    def calculate(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return int(left == right)
        if op == "<>":
            return int(left != right)
        if op == "<":
            return int(left < right)
        if op == "<=":
            return int(left <= right)
        if op == ">":
            return int(left > right)
        return int(left >= right)

    results = {}
    active = set()

    def evaluate(start):
        tasks = [("cell", start)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]

                if name in results:
                    values.append(results[name])
                elif name not in cells:
                    values.append(0)
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name]
                    node = (
                        parse(content[1:])
                        if content.startswith("=")
                        else int(content)
                    )
                    tasks.append(("finish", name))
                    tasks.append(("eval", node))

            elif kind == "finish":
                name = task[1]
                results[name] = values[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]

                if isinstance(node, int):
                    values.append(node)
                elif isinstance(node, str):
                    tasks.append(("cell", node))
                elif node[0] == "neg":
                    tasks.append(("negate",))
                    tasks.append(("eval", node[1]))
                elif node[0] == "binary":
                    _, op, left, right = node
                    tasks.append(("binary_left", op, right))
                    tasks.append(("eval", left))
                else:
                    _, function, arguments = node
                    if function == "IF":
                        tasks.append(("choose", arguments[1], arguments[2]))
                        tasks.append(("eval", arguments[0]))
                    else:
                        iterator = argument_nodes(arguments)
                        initial = 0 if function == "SUM" else None
                        tasks.append(("aggregate", function, iterator, initial))

            elif kind == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    _, op, right = task
                    tasks.append(("binary_right", op, left))
                    tasks.append(("eval", right))

            elif kind == "binary_right":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                else:
                    values.append(calculate(task[1], task[2], right))

            elif kind == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                _, function, iterator, accumulator = task
                node = next(iterator, None)

                if node is None:
                    values.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(
                        ("aggregate_value", function, iterator, accumulator)
                    )
                    tasks.append(("eval", node))

            elif kind == "aggregate_value":
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                else:
                    _, function, iterator, accumulator = task
                    if accumulator is None:
                        accumulator = value
                    elif function == "SUM":
                        accumulator += value
                    elif function == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)

                    tasks.append(
                        ("aggregate", function, iterator, accumulator)
                    )

    for name in cells:
        if name not in results:
            evaluate(name)

    return {name: results[name] for name in cells}
